			"--dsw-alias-bg-base": "#141626",
			"--dsw-alias-bg-layer-1": "#191b2e",
			"--dsw-alias-bg-layer-2": "#1e2030",
			"--dsw-alias-bg-layer-3": "#232536",
			"--dsw-alias-bg-module-platform": "#232536",
